const essaySections = () =>
  site.essay.blocks
    .filter((block) => block.type === "h2")
    .map((block) => block.text);

const tocBlock = () => `
  <div class="margin-block">
    <p class="label">In this piece</p>
    <nav class="toc" aria-label="In this piece">
      ${essaySections()
        .map((text) => `<a href="#${slug(text)}">${text}</a>`)
        .join("")}
    </nav>
  </div>`;

// One version list, reused by the History panel and the Rev. 01 margin.
// The version being read is marked, not linked.
const versionList = (version) => `
  <ul class="version-list">
    ${essayVersions
      .map((item) => {
        const here = item.id === version.id;
        const stamp = `${item.label} · ${item.date}`;
        const head = here
          ? `<span class="version-stamp" aria-current="true">${stamp}</span>`
          : `<a class="version-stamp" href="#" data-version="${item.id}" data-mode="reading">${stamp} →</a>`;
        return `<li class="${here ? "is-here" : ""}">${head}<p>${item.current ? "Current" : "First published"}</p></li>`;
      })
      .join("")}
  </ul>`;

function essay() {
  const version =
    essayVersions.find((item) => item.id === state.version) || essayVersions[0];
  const current = version.current;
  // Change bars belong to the current version only. Rev. 01 is a plain, readable old version.
  const history = state.mode === "history" && current;
  return `
    ${header("Writing")}
    <main>
    <article class="essay ${history ? "history" : "reading"} ${current ? "current" : "archived"}">
      <header class="essay-head">
        <p class="kicker">Writing / ${site.essay.category}</p>
        <h1>${site.essay.title}</h1>
        <p class="deck">${site.essay.deck}</p>
        <p class="meta">${current ? `First published ${site.essay.published} · Revised ${site.essay.revised} · ${version.reading}` : `First published ${version.date} · ${version.reading}`}</p>
        ${
          !current
            ? `<div class="version-banner" role="note">
          <p class="version-banner-title"><strong>You're reading ${version.label}.</strong> First published ${version.date}.</p>
          <p class="version-banner-links"><a href="#" data-version="rev-02" data-mode="reading">Read the current version →</a><a href="#" data-version="rev-02" data-mode="history">See what changed →</a></p>
        </div>`
            : ""
        }
      </header>

      <div class="essay-grid">
        <div class="body">${essayBody(version)}</div>
        <aside class="essay-margin">
          ${
            current && !history
              ? `
            <div class="revision-rail">
              <p class="label">History</p>
              <p class="rail-stamp">Rev. 02 · ${site.essay.revised}</p>
              <a class="rail-link" href="#" data-mode="history">See history →</a>
              <p class="rail-first">First published ${site.essay.published}.</p>
            </div>
            ${tocBlock()}
            <div class="margin-block">
              <p class="label">See also</p>
              <ul class="see">
                <li><a href="#">Organizational Changelog</a><span>Because both ask what a structure helps an organization remember.</span></li>
                <li><a href="#">Trust First</a><span>Because ownership without trust becomes blame.</span></li>
              </ul>
            </div>
            <div class="margin-block">
              <p class="label">Still thinking</p>
              <p class="margin-prose">Does removing a central meeting work the same way in a remote-first org? I don't have a clean answer yet.</p>
            </div>
          `
              : ""
          }
          ${
            history
              ? `
            <div class="history-panel">
              <p class="label">Versions</p>
              ${versionList(version)}
              <p class="label">What changed</p>
              <p class="history-summary">${version.summary}</p>
              <a class="rail-link" href="#" data-mode="reading">Back to reading ←</a>
            </div>
          `
              : ""
          }
          ${
            !current
              ? `
            <div class="history-panel">
              <p class="label">Versions</p>
              ${versionList(version)}
              <a class="rail-link" href="#" data-version="rev-02" data-mode="history">See what changed →</a>
            </div>
            ${tocBlock()}
          `
              : ""
          }
        </aside>
      </div>

      ${
        history
          ? `
        <section class="then-now" aria-labelledby="then-now-title">
          <h2 class="label" id="then-now-title">Then / Now</h2>
          <div class="then-now-grid">
            <div class="then">
              <p class="label">Rev. 01 · ${site.essay.published}</p>
              <p>${site.essay.thenNow.then}</p>
            </div>
            <div class="now">
              <p class="label">Rev. 02 · ${site.essay.revised}</p>
              <p>${site.essay.thenNow.now}</p>
            </div>
          </div>
          <p class="then-now-note">${site.essay.thenNow.note}</p>
        </section>
      `
          : ""
      }

      <section class="revision-log" aria-labelledby="version-log-title">
        <h2 class="label" id="version-log-title">History</h2>
        <ul class="version-log">
          ${essayVersions
            .map(
              (item) => `
          <li class="${item.id === version.id ? "is-here" : ""}">
            <div class="version-log-head"><a href="#" data-version="${item.id}" data-mode="${item.current ? state.mode : "reading"}"${item.id === version.id ? ' aria-current="true"' : ""}>${item.label} · ${item.date}</a><span class="${item.current ? "is-current" : ""}">${item.current ? "Current" : "First published"}</span></div>
            <p>${item.summary}</p>
          </li>`,
            )
            .join("")}
        </ul>
        ${
          history
            ? ""
            : `
        <details class="revision-details">
          <summary>Then and now</summary>
          <div class="then-now-compact">
            <div class="then"><p class="label">Then</p><p>${site.essay.thenNow.then}</p></div>
            <div class="now"><p class="label">Now</p><p>${site.essay.thenNow.now}</p></div>
          </div>
          <p class="then-now-note">${site.essay.thenNow.note}</p>
        </details>`
        }
      </section>

      <footer class="essay-foot">
        <h2 class="label">Read alongside</h2>
        <div class="alongside">
          <a href="#">Organizational Changelog<span>On remembering what an organization learns.</span></a>
          <a href="#">Trust First<span>On the risk of extending trust before proof.</span></a>
        </div>
        <p class="folio"><span>${site.name}</span><span>${site.essay.title}</span><span>${version.label} · ${version.date.split(" ").pop()}</span></p>
      </footer>
    </article>
    </main>`;
}

