const MODES = {
  reading: {
    number: "01",
    label: "Reading",
    thesis: "Read the current essay; the history is a quiet rail.",
    what: "A clean reading column. The margin shows the current version, a “See history” link, and the first publication date. The version log sits at the end.",
    risk: "The soft hint may still be too quiet; the reader may never open the history.",
  },
  history: {
    number: "02",
    label: "History",
    thesis: "See the essay's versions without leaving the essay.",
    what: "The current version with change bars on the rewritten passages, a version panel, and a curated Then / Now. Rev. 01 is readable in full.",
    risk: "Can become process theater. Mark only meaningful changes; big rewrites should be versions, not a diff of every sentence.",
  },
};

const VIEWS = {
  home: { label: "Home", render: home },
  essay: { label: "Essay", render: essay },
  about: { label: "About", render: about },
  archive: { label: "Archive", render: archive },
  readme: { label: "README", render: readme },
};

const state = {
  view: "home",
  mode: "reading",
  version: "rev-02",
  mobile: false,
  notes: false,
};

const stage = document.getElementById("stage");
const modeTabs = document.getElementById("mode-tabs");
const viewTabs = document.getElementById("view-tabs");
const notesPanel = document.getElementById("notes-panel");
const notesBody = document.getElementById("notes-body");
const mobileToggle = document.getElementById("mobile-toggle");
const notesToggle = document.getElementById("notes-toggle");
const notesClose = document.getElementById("notes-close");

function notesHTML() {
  const mode = MODES[state.mode];
  return `
    <p class="notes-direction">Round 6 · ${mode.number} ${mode.label}</p>
    <h2>${mode.thesis}</h2>
    <dl>
      <dt>What it does</dt><dd>${mode.what}</dd>
      <dt>Where it might fail</dt><dd>${mode.risk}</dd>
    </dl>

    <div class="notes-block">
      <p class="notes-kicker">The home</p>
      <p>The letter carries the Shopify proof and signs off “— J.” The main column is now a position: three current beliefs and the recent revisions. The career journey moved to About.</p>
    </div>

    <div class="notes-block">
      <p class="notes-kicker">The history model</p>
      <p>Essays have versions, not just notes. Rev. 02 is current; Rev. 01 stays readable in full. History mode adds change bars on the rewritten passages, a version panel, and a curated Then / Now. The soft hint is always in the margin.</p>
    </div>

    <div class="notes-block">
      <p class="notes-kicker">The rest</p>
      <ul>
        <li>Ash + Newsreader display + Source Serif 4 body.</li>
        <li>About holds the career journey; the home keeps one Shopify line.</li>
        <li>README keeps today's structure; the Sagan coda is collapsed.</li>
        <li>Folio at the foot of essays.</li>
      </ul>
    </div>

    <div class="notes-questions">
      <p class="notes-kicker">Ask yourself</p>
      <ul>
        <li>Does the home feel like a position now, or still a bio with lists?</li>
        <li>Is the Shopify line proof without being a shill?</li>
        <li>Does “— J.” feel right on the home?</li>
        <li>Does the version model handle a big rewrite honestly?</li>
        <li>Does History mode feel dialed in now, or still weird?</li>
        <li>Does About give the career journey a real home?</li>
      </ul>
    </div>`;
}

function renderTabs() {
  modeTabs.innerHTML = Object.entries(MODES)
    .map(
      ([key, mode]) =>
        `<button class="lab-tab ${key === state.mode ? "is-active" : ""}" data-mode="${key}" type="button"><span>${mode.number}</span>${mode.label}</button>`,
    )
    .join("");

  viewTabs.innerHTML = Object.entries(VIEWS)
    .map(
      ([key, view]) =>
        `<button class="lab-tab lab-tab-view ${key === state.view ? "is-active" : ""}" data-view="${key}" type="button">${view.label}</button>`,
    )
    .join("");
}

function render() {
  stage.innerHTML = `<div class="proto" data-skin="ash"><div class="page">${VIEWS[state.view].render()}</div></div>`;
  stage.classList.toggle("mobile", state.mobile);
  mobileToggle.classList.toggle("is-active", state.mobile);
  mobileToggle.setAttribute("aria-pressed", String(state.mobile));
  notesBody.innerHTML = notesHTML();
  notesPanel.hidden = !state.notes;
  notesToggle.classList.toggle("is-active", state.notes);
  notesToggle.setAttribute("aria-pressed", String(state.notes));
  document.body.classList.toggle("notes-open", state.notes);
  renderTabs();
  try {
    const versionPart =
      state.view === "essay" && state.version !== "rev-02"
        ? `/${state.version}`
        : "";
    history.replaceState(
      null,
      "",
      `#${state.view}/${state.mode}${versionPart}`,
    );
  } catch {
    // file:// origins can refuse history updates; the lab still works without them.
  }
}

modeTabs.addEventListener("click", (event) => {
  const button = event.target.closest("[data-mode]");
  if (!button) return;
  state.mode = button.dataset.mode;
  state.version = "rev-02";
  if (state.view !== "essay") state.view = "essay";
  render();
  window.scrollTo(0, 0);
});

viewTabs.addEventListener("click", (event) => {
  const button = event.target.closest("[data-view]");
  if (!button) return;
  state.view = button.dataset.view;
  render();
});

stage.addEventListener("click", (event) => {
  const versionLink = event.target.closest("[data-version]");
  if (versionLink) {
    event.preventDefault();
    state.version = versionLink.dataset.version;
    if (versionLink.dataset.mode) state.mode = versionLink.dataset.mode;
    if (versionLink.dataset.goto) state.view = versionLink.dataset.goto;
    render();
    window.scrollTo(0, 0);
    return;
  }

  const modeLink = event.target.closest("[data-mode]");
  if (modeLink) {
    event.preventDefault();
    state.mode = modeLink.dataset.mode;
    state.version = "rev-02";
    if (modeLink.dataset.goto) state.view = modeLink.dataset.goto;
    render();
    window.scrollTo(0, 0);
    return;
  }

  const link = event.target.closest("[data-goto]");
  if (link) {
    event.preventDefault();
    state.view = link.dataset.goto;
    render();
    window.scrollTo(0, 0);
    return;
  }

  // In-page anchors (TOC, About rail, README TL;DR): scroll and move focus
  // without touching the lab's #view/mode hash.
  const anchor = event.target.closest('a[href^="#"]:not([href="#"])');
  if (anchor) {
    const target = document.getElementById(
      anchor.getAttribute("href").slice(1),
    );
    if (!target) return;
    event.preventDefault();
    const reduce = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    target.setAttribute("tabindex", "-1");
    target.scrollIntoView({
      behavior: reduce ? "auto" : "smooth",
      block: "start",
    });
    target.focus({ preventScroll: true });
    return;
  }

  const dead = event.target.closest('a[href="#"]');
  if (dead) event.preventDefault();
});

mobileToggle.addEventListener("click", () => {
  state.mobile = !state.mobile;
  render();
});

notesToggle.addEventListener("click", () => {
  state.notes = !state.notes;
  render();
});

notesClose.addEventListener("click", () => {
  state.notes = false;
  render();
});

function readHash() {
  const [view, mode, version] = window.location.hash
    .replace("#", "")
    .split("/");
  if (!VIEWS[view]) return false;
  state.view = view;
  if (MODES[mode]) state.mode = mode;
  state.version = essayVersions.some((item) => item.id === version)
    ? version
    : "rev-02";
  return true;
}

window.addEventListener("hashchange", () => {
  // In-page anchors (TOC, README TL;DR) are not lab routes; leave state alone.
  if (readHash()) render();
});

readHash();
render();
